"use client";
import { useState } from "react"; import { installTire } from "@/app/actions/tires"; import { Button } from "@/components/ui/button";
export function TireInstallationForm({unitId}:{unitId:string}){const [message,setMessage]=useState("");return <form className="space-y-3 rounded-lg border bg-white p-4" onSubmit={async(e)=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await installTire({unitId,position:f.get("position"),brand:f.get("brand"),installedOn:f.get("installedOn"),costCentavos:Number(f.get("costCentavos")),nextDueDate:String(f.get("nextDueDate")||"")||undefined,nextDueMileage:f.get("nextDueMileage")?Number(f.get("nextDueMileage")):undefined});setMessage("Tire saved.");}catch{setMessage("Add a tire and at least one due value.");}}}><h2 className="font-semibold">Install tire</h2><select name="position" className="min-h-11 w-full rounded border p-3"><option value="front">Front</option><option value="rear_left">Rear-left</option><option value="rear_right">Rear-right</option></select><input required name="brand" placeholder="Brand" className="min-h-11 w-full rounded border p-3"/><input required name="installedOn" type="date" className="min-h-11 w-full rounded border p-3"/><input required name="costCentavos" type="number" min="0" placeholder="Cost in centavos" className="min-h-11 w-full rounded border p-3"/><input name="nextDueDate" type="date" className="min-h-11 w-full rounded border p-3"/><input name="nextDueMileage" type="number" min="0" placeholder="Next due mileage" className="min-h-11 w-full rounded border p-3"/><Button type="submit">Save tire</Button>{message&&<p className="text-sm text-slate-600">{message}</p>}</form>}
